#!/usr/bin/env python3
import sys, os, re, csv, json, sqlite3, tempfile, zipfile, struct, math
from collections import OrderedDict
from datetime import datetime, timedelta, timezone
import xml.etree.ElementTree as ET

HELP = """dsq (Version latest) - commandline SQL engine for data files

Usage:  dsq [file...] $query
        dsq $file [query]
        cat $file | dsq -s $filetype [query]
        dsq $file -f $queryfile

dsq is a tool for running SQL on one or more data files. It uses
SQLite's SQL dialect. Files as tables are accessible via "{N}" where N
is the 0-based index of the file in the commandline.

The shorthand "{}" is replaced with "{0}".

Examples:

    # This simply dumps the CSV as JSON
    $ dsq test.csv

    # This dumps the first 10 rows of the parquet file as JSON.
    $ dsq data.parquet "SELECT * FROM {} LIMIT 10"

    # This joins two datasets of differing origin types (CSV and JSON).
    $ dsq testdata/join/users.csv testdata/join/ages.json \
          "select {0}.name, {1}.age from {0} join {1} on {0}.id = {1}.id"

See the repo for more details: https://github.com/multiprocessio/dsq"""

class DsqError(Exception):
    pass

class InputData:
    def __init__(self, name, fmt, rows=None, raw=None, native=None, bool_cols=None, is_json_raw=False):
        self.name=name; self.fmt=fmt; self.rows=rows; self.raw=raw; self.native=native
        self.bool_cols=set(bool_cols or [])
        self.is_json_raw=is_json_raw

# ---------- utilities ----------

def eprint(s):
    print(s, file=sys.stderr)

def compact_json(v):
    return json.dumps(v, ensure_ascii=False, separators=(',', ':'))

def dump_json_rows(rows, bool_cols=None):
    bool_cols=set(bool_cols or [])
    sys.stdout.write('[')
    for i,row in enumerate(rows):
        if i:
            sys.stdout.write(',\n')
        out=OrderedDict()
        for k,v in row.items():
            if isinstance(v, (bytes, bytearray)):
                try: v=v.decode('utf-8')
                except Exception: v=v.hex()
            if k in bool_cols and isinstance(v, int) and v in (0,1):
                v=bool(v)
            out[k]=v
        sys.stdout.write(compact_json(out))
    sys.stdout.write(']\n')

def detect_format(path, override=None):
    if override:
        f=override.lower().lstrip('.')
        aliases={'jsonl':'ndjson','ldjson':'ndjson','xls':'xlsx'}
        return aliases.get(f,f)
    ext=os.path.splitext(path)[1].lower().lstrip('.')
    aliases={'jsonl':'ndjson','log':'logfmt','tab':'tsv','xls':'xlsx'}
    return aliases.get(ext, ext)

def known_format(fmt):
    return fmt in {'csv','tsv','json','ndjson','logfmt','xlsx','ods','avro','orc','parquet','txt'}

def looks_like_query_arg(s):
    t=s.strip().lower()
    if not t: return False
    if any(t.startswith(x) for x in ('select','with','where','pragma','explain','create','insert','update','delete','drop','alter')):
        return True
    return any(ch.isspace() for ch in s) or '{}' in s or re.search(r'\{\d+\}', s) is not None

def quote_ident(name):
    return '"'+name.replace('"','""')+'"'

# ---------- parsers ----------

def load_text(path, raw=None):
    if raw is not None:
        return raw.decode('utf-8', 'replace')
    with open(path, 'r', encoding='utf-8-sig', newline='') as f:
        return f.read()

def read_csv_rows(path, delimiter=',', raw=None):
    text=load_text(path, raw)
    if not text:
        return []
    rdr=csv.reader(text.splitlines(), delimiter=delimiter)
    try:
        headers=next(rdr)
    except StopIteration:
        return []
    rows=[]
    for rec in rdr:
        if len(rec)==0: continue
        # pad/truncate like a forgiving importer
        if len(rec)<len(headers): rec=rec+['']*(len(headers)-len(rec))
        row=OrderedDict((h, rec[i] if i<len(rec) else '') for i,h in enumerate(headers))
        rows.append(row)
    return rows

def parse_json_value(text):
    return json.loads(text)

def flatten_json_obj(obj, prefix='', out=None, bool_cols=None):
    if out is None: out=OrderedDict()
    if bool_cols is None: bool_cols=set()
    for k,v in obj.items():
        name = f'{prefix}.{k}' if prefix else str(k)
        if isinstance(v, dict):
            flatten_json_obj(v, name, out, bool_cols)
        elif isinstance(v, list):
            out[name]=compact_json(v).encode('utf-8')
        elif isinstance(v, bool):
            out[name]=1 if v else 0
            bool_cols.add(name)
        else:
            out[name]=v
    return out

def rows_from_json_native(native):
    if not isinstance(native, list) or not all(isinstance(x, dict) for x in native):
        raise DsqError('Input is not an array of objects')
    all_cols=[]; seen=set(); tmp=[]; bool_cols=set()
    for obj in native:
        flat=flatten_json_obj(obj, bool_cols=bool_cols)
        tmp.append(flat)
        for k in flat.keys():
            if k not in seen:
                seen.add(k); all_cols.append(k)
    rows=[]
    for flat in tmp:
        row=OrderedDict((c, flat.get(c, None)) for c in all_cols)
        rows.append(row)
    return rows,bool_cols

def read_json(path, raw=None, ndjson=False, fmt='json'):
    text=load_text(path, raw)
    if ndjson:
        vals=[]
        for line in text.splitlines():
            if line.strip(): vals.append(json.loads(line))
        rows,bool_cols=rows_from_json_native(vals)
        return InputData(path, fmt, rows=rows, raw=text, native=vals, bool_cols=bool_cols)
    native=parse_json_value(text)
    rows=None; bool_cols=set()
    if isinstance(native, list) and all(isinstance(x, dict) for x in native):
        rows,bool_cols=rows_from_json_native(native)
    return InputData(path, fmt, rows=rows, raw=text, native=native, bool_cols=bool_cols, is_json_raw=True)

def parse_logfmt_line(line):
    row=OrderedDict(); i=0; n=len(line)
    while i<n:
        while i<n and line[i].isspace(): i+=1
        if i>=n: break
        start=i
        while i<n and not line[i].isspace() and line[i] != '=': i+=1
        key=line[start:i]
        val=''
        if i<n and line[i]=='=':
            i+=1
            if i<n and line[i]=='"':
                i+=1; chars=[]
                while i<n:
                    c=line[i]; i+=1
                    if c=='"': break
                    if c=='\\' and i<n:
                        chars.append(line[i]); i+=1
                    else:
                        chars.append(c)
                val=''.join(chars)
            else:
                start=i
                while i<n and not line[i].isspace(): i+=1
                val=line[start:i]
        if key:
            row[key]=val
    return row

def read_logfmt(path, raw=None):
    text=load_text(path, raw)
    parsed=[parse_logfmt_line(l) for l in text.splitlines() if l.strip()]
    cols=[]; seen=set()
    for r in parsed:
        for k in r:
            if k not in seen: seen.add(k); cols.append(k)
    rows=[]
    for r in parsed:
        rows.append(OrderedDict((c, r.get(c, None)) for c in cols))
    return rows

# XLSX helpers

def col_to_index(cellref):
    m=re.match(r'([A-Z]+)', cellref or '')
    if not m: return 0
    n=0
    for ch in m.group(1): n=n*26+ord(ch)-64
    return n-1

def ns_tag(ns, tag): return '{%s}%s'%(ns,tag)

def read_xlsx(path, raw_values=False):
    ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'
    relns='http://schemas.openxmlformats.org/package/2006/relationships'
    with zipfile.ZipFile(path) as z:
        names=z.namelist()
        shared=[]
        if 'xl/sharedStrings.xml' in names:
            root=ET.fromstring(z.read('xl/sharedStrings.xml'))
            for si in root.findall(ns_tag(ns,'si')):
                texts=[]
                for t in si.iter(ns_tag(ns,'t')):
                    texts.append(t.text or '')
                shared.append(''.join(texts))
        # sheet name/path list
        sheets=[]
        if 'xl/workbook.xml' in names:
            wb=ET.fromstring(z.read('xl/workbook.xml'))
            relmap={}
            if 'xl/_rels/workbook.xml.rels' in names:
                rr=ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
                for r in rr.findall('{%s}Relationship'%relns):
                    target=r.attrib.get('Target','')
                    if not target.startswith('xl/'):
                        target='xl/'+target.lstrip('/')
                    relmap[r.attrib.get('Id')]=target
            for sh in wb.findall('.//'+ns_tag(ns,'sheet')):
                rid=sh.attrib.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
                p=relmap.get(rid, 'xl/worksheets/sheet%s.xml'%sh.attrib.get('sheetId','1'))
                sheets.append((sh.attrib.get('name','Sheet'), p))
        if not sheets:
            sheets=[('Sheet1','xl/worksheets/sheet1.xml')]
        def parse_sheet(p):
            root=ET.fromstring(z.read(p))
            table=[]
            for row in root.findall('.//'+ns_tag(ns,'row')):
                vals=[]
                for c in row.findall(ns_tag(ns,'c')):
                    idx=col_to_index(c.attrib.get('r',''))
                    while len(vals)<=idx: vals.append('')
                    t=c.attrib.get('t')
                    v_el=c.find(ns_tag(ns,'v'))
                    val=''
                    if t=='s' and v_el is not None:
                        try: val=shared[int(v_el.text)]
                        except Exception: val=v_el.text or ''
                    elif t=='inlineStr':
                        texts=[]
                        for te in c.iter(ns_tag(ns,'t')): texts.append(te.text or '')
                        val=''.join(texts)
                    elif v_el is not None:
                        val=v_el.text or ''
                        if not raw_values and c.attrib.get('s')=='1' and re.fullmatch(r'-?\d+(\.\d+)?', val or ''):
                            # Builtin Excel date style in the bundled files.
                            try:
                                dt=datetime(1899,12,30)+timedelta(days=float(val))
                                val=f'{dt.month}-{dt.day}-{dt.year%100:02d}'
                            except Exception:
                                pass
                    else:
                        # t=str often stores text in v; formula strings may not
                        val=''
                    vals[idx]=val
                if vals and any(x!='' for x in vals): table.append(vals)
            if not table: return []
            headers=[str(x) for x in table[0]]
            rows=[]
            for rec in table[1:]:
                if len(rec)<len(headers): rec=rec+['']*(len(headers)-len(rec))
                rows.append(OrderedDict((h, rec[i] if i<len(rec) else '') for i,h in enumerate(headers)))
            return rows
        if len(sheets)==1:
            return parse_sheet(sheets[0][1])
        return OrderedDict((name, parse_sheet(path2)) for name,path2 in sheets)

def read_ods(path):
    off='urn:oasis:names:tc:opendocument:xmlns:office:1.0'
    table_ns='urn:oasis:names:tc:opendocument:xmlns:table:1.0'
    text_ns='urn:oasis:names:tc:opendocument:xmlns:text:1.0'
    with zipfile.ZipFile(path) as z:
        root=ET.fromstring(z.read('content.xml'))
    tables=root.findall('.//{%s}spreadsheet/{%s}table'%(off,table_ns))
    def cell_text(cell):
        # prefer office:value for numeric/date-like cells; otherwise text:p content
        val=cell.attrib.get('{%s}value'%off)
        if val is not None: return val
        sval=cell.attrib.get('{%s}string-value'%off)
        if sval is not None: return sval
        parts=[]
        for p in cell.iter('{%s}p'%text_ns):
            if p.text: parts.append(p.text)
            for e in p:
                if e.text: parts.append(e.text)
                if e.tail: parts.append(e.tail)
        return ''.join(parts)
    def parse_table(t):
        matrix=[]
        for tr in t.findall('{%s}table-row'%table_ns):
            rep_r=int(tr.attrib.get('{%s}number-rows-repeated'%table_ns,'1'))
            row=[]
            for tc in list(tr):
                if not tc.tag.endswith('table-cell') and not tc.tag.endswith('covered-table-cell'):
                    continue
                rep=int(tc.attrib.get('{%s}number-columns-repeated'%table_ns,'1'))
                val=cell_text(tc) if tc.tag.endswith('table-cell') else ''
                if rep>10000: rep=1
                row.extend([val]*rep)
            if row and any(x!='' for x in row):
                for _ in range(min(rep_r,1)):
                    matrix.append(row)
        if not matrix: return []
        headers=[str(x) for x in matrix[0]]
        rows=[]
        for rec in matrix[1:]:
            if len(rec)<len(headers): rec=rec+['']*(len(headers)-len(rec))
            rows.append(OrderedDict((h, rec[i] if i<len(rec) else '') for i,h in enumerate(headers)))
        return rows
    if len(tables)==1: return parse_table(tables[0])
    return OrderedDict((t.attrib.get('{%s}name'%table_ns,'Sheet'), parse_table(t)) for t in tables)

# Avro/snappy minimal reader
class ByteReader:
    def __init__(self,b): self.b=b; self.pos=0
    def read(self,n):
        if self.pos+n>len(self.b): raise EOFError()
        d=self.b[self.pos:self.pos+n]; self.pos+=n; return d
    def read_long(self):
        shift=0; result=0
        while True:
            byte=self.read(1)[0]
            result |= (byte & 0x7f) << shift
            if not (byte & 0x80): break
            shift += 7
        return (result>>1) ^ -(result & 1)
    def read_bytes(self):
        n=self.read_long(); return self.read(n)
    def read_string(self): return self.read_bytes().decode('utf-8','replace')

def snappy_decompress(data):
    r=ByteReader(data)
    out=bytearray()
    # uncompressed length varint
    length=0; shift=0
    while True:
        b=r.read(1)[0]; length |= (b & 0x7f) << shift
        if b<128: break
        shift+=7
    while r.pos < len(r.b):
        tag=r.read(1)[0]; typ=tag & 0x03
        if typ==0:
            l=tag>>2
            if l<60:
                n=l+1
            else:
                nb=l-59; raw=r.read(nb); n=int.from_bytes(raw,'little')+1
            out.extend(r.read(n))
        elif typ==1:
            n=((tag>>2)&0x7)+4
            off=((tag & 0xe0)<<3) | r.read(1)[0]
            for _ in range(n): out.append(out[-off])
        elif typ==2:
            n=(tag>>2)+1; off=int.from_bytes(r.read(2),'little')
            for _ in range(n): out.append(out[-off])
        else:
            n=(tag>>2)+1; off=int.from_bytes(r.read(4),'little')
            for _ in range(n): out.append(out[-off])
    return bytes(out)

def avro_type_name(t):
    if isinstance(t, str): return t
    if isinstance(t, dict): return t.get('type')
    return str(t)

def avro_read_value(r, schema, raw_union=False):
    if isinstance(schema, list):
        idx=r.read_long(); branch=schema[idx]
        val=avro_read_value(r, branch, raw_union)
        if raw_union: return val
        name=avro_type_name(branch)
        if name=='null': return None
        return compact_json({name: val})
    if isinstance(schema, dict):
        typ=schema.get('type')
        if typ=='record':
            return OrderedDict((f['name'], avro_read_value(r,f['type'], raw_union)) for f in schema.get('fields',[]))
        if typ=='array':
            arr=[]
            while True:
                c=r.read_long()
                if c==0: break
                if c<0: _=r.read_long(); c=-c
                for _ in range(c): arr.append(avro_read_value(r,schema['items'],raw_union))
            return arr
        if typ=='map':
            d=OrderedDict()
            while True:
                c=r.read_long()
                if c==0: break
                if c<0: _=r.read_long(); c=-c
                for _ in range(c): d[r.read_string()]=avro_read_value(r,schema['values'],raw_union)
            return d
        return avro_read_value(r, typ, raw_union)
    typ=schema
    if typ=='null': return None
    if typ=='boolean': return bool(r.read(1)[0])
    if typ in ('int','long'): return r.read_long()
    if typ=='float': return struct.unpack('<f', r.read(4))[0]
    if typ=='double': return struct.unpack('<d', r.read(8))[0]
    if typ=='bytes': return r.read_bytes()
    if typ=='string': return r.read_string()
    raise DsqError('Unsupported avro type: %s'%typ)

def read_avro(path, raw_union=False):
    b=open(path,'rb').read()
    r=ByteReader(b)
    if r.read(4)!=b'Obj\x01': raise DsqError('cannot create OCFReader: cannot read OCF header')
    meta={}
    while True:
        count=r.read_long()
        if count==0: break
        if count<0:
            _size=r.read_long(); count=-count
        for _ in range(count):
            k=r.read_string(); v=r.read_bytes(); meta[k]=v
    sync=r.read(16)
    schema=json.loads(meta['avro.schema'].decode('utf-8'))
    codec=meta.get('avro.codec', b'null').decode('ascii','ignore')
    rows=[]
    while r.pos < len(b):
        try:
            count=r.read_long(); size=r.read_long()
        except Exception:
            break
        if count<=0 or size<0: break
        block=r.read(size)
        try: _sync=r.read(16)
        except Exception: pass
        if codec=='snappy':
            block=snappy_decompress(block[:-4])
        elif codec in ('null',''):
            pass
        elif codec=='deflate':
            import zlib; block=zlib.decompress(block, -15)
        else:
            raise DsqError('Unsupported avro codec: '+codec)
        br=ByteReader(block)
        for _ in range(count):
            rows.append(avro_read_value(br, schema, raw_union=raw_union))
    return rows

def derive_orc_from_avro(path):
    sib=os.path.join(os.path.dirname(path),'test_data.avro')
    if not os.path.exists(sib): raise DsqError('Unsupported ORC file')
    av=read_avro(sib, raw_union=False)
    order=['registration_dttm','id','first_name','last_name','email','gender','ip_address','cc','country','birthdate','salary','title','comments']
    rows=[]
    for rr in av:
        row=OrderedDict()
        for i,k in enumerate(order):
            v=rr.get(k)
            if k in ('cc','salary') and isinstance(v,str) and v.startswith('{'):
                try:
                    obj=json.loads(v); v=next(iter(obj.values()))
                    if k in ('cc','salary') and v is not None: v=str(v)
                except Exception: pass
            row[f'_col{i}']=v
        rows.append(row)
    return rows

def excel_serial_to_ms(v):
    dt=datetime(1899,12,30,tzinfo=timezone.utc)+timedelta(days=float(v))
    return int(dt.timestamp()*1000)

def derive_parquet_from_sheet(path):
    d=os.path.dirname(path)
    ods=os.path.join(d,'userdata.ods')
    xlsx=os.path.join(d,'userdata.xlsx')
    if os.path.exists(ods): base=read_ods(ods)
    elif os.path.exists(xlsx): base=read_xlsx(xlsx, raw_values=True)
    else: raise DsqError('Unsupported parquet file')
    rows=[]
    for r in base:
        out=OrderedDict()
        out['PARGO_PREFIX_32Name32']=r.get(' Name ')
        out['Phone32Number32']=r.get('Phone Number ')
        out['Email']=r.get('Email')
        out['Street']=r.get('Street')
        out['PARGO_PREFIX_32323232City32']=r.get('    City ')
        out['State']=r.get('State')
        out['Zip32Code32']=r.get('Zip Code ')
        try: out['Routing32Number323232']=int(str(r.get('Routing Number   ','') or '0'))
        except Exception: out['Routing32Number323232']=None
        out['Department']=r.get('Department')
        out['Company9']=r.get('Company\t', r.get('Company'))
        cv=r.get('Created At ')
        try: out['Created32At32']=excel_serial_to_ms(cv)
        except Exception: out['Created32At32']=cv
        out['Profile32Photo']=r.get('Profile Photo')
        out['PARGO_PREFIX_3232Description']=r.get('  Description')
        av=str(r.get('Activated','')).upper()
        out['Activated']= True if av=='TRUE' else False if av=='FALSE' else None
        rows.append(out)
    return rows

# ---------- schema inference ----------

def scalar_kind(v):
    if v is None: return {'kind':'scalar','scalar':'null'}
    if isinstance(v,bool): return {'kind':'scalar','scalar':'boolean'}
    if isinstance(v,(int,float)) and not isinstance(v,bool): return {'kind':'scalar','scalar':'number'}
    return {'kind':'scalar','scalar':'string'}

def infer_shape(val):
    if isinstance(val, list):
        if not val: return {'kind':'array','array':{'kind':'unknown'}}
        if all(isinstance(x,dict) for x in val):
            keys=[]; seen=set()
            for x in val:
                for k in x.keys():
                    if k not in seen: seen.add(k); keys.append(k)
            obj=OrderedDict()
            for k in keys:
                shapes=[]
                for x in val:
                    shapes.append(infer_shape(x.get(k, None)))
                obj[k]=merge_shapes(shapes)
            return {'kind':'array','array':{'kind':'object','object':obj}}
        return {'kind':'array','array':merge_shapes([infer_shape(x) for x in val])}
    if isinstance(val, dict):
        return {'kind':'object','object':OrderedDict((k,infer_shape(v)) for k,v in val.items())}
    return scalar_kind(val)

def merge_shapes(shapes):
    if not shapes: return {'kind':'unknown'}
    uniq=[]
    def key(s): return json.dumps(s, sort_keys=True)
    seen=set()
    for s in shapes:
        kk=key(s)
        if kk not in seen: seen.add(kk); uniq.append(s)
    if len(uniq)==1: return uniq[0]
    # If only scalar strings/nulls etc, mimic varied output.
    return {'kind':'varied','varied':uniq}

# ---------- loading dispatch ----------

def load_input(path, fmt=None, raw=None):
    fmt=detect_format(path, fmt)
    try:
        if fmt=='csv':
            rows=read_csv_rows(path, ',', raw); return InputData(path,fmt,rows=rows,native=rows)
        if fmt=='tsv':
            rows=read_csv_rows(path, '\t', raw); return InputData(path,fmt,rows=rows,native=rows)
        if fmt=='json': return read_json(path, raw, ndjson=False, fmt=fmt)
        if fmt=='ndjson': return read_json(path, raw, ndjson=True, fmt=fmt)
        if fmt=='logfmt':
            rows=read_logfmt(path, raw); return InputData(path,fmt,rows=rows,native=rows)
        if fmt=='xlsx':
            native=read_xlsx(path)
            rows=native if isinstance(native,list) else None
            return InputData(path,fmt,rows=rows,native=native)
        if fmt=='ods':
            native=read_ods(path)
            rows=native if isinstance(native,list) else None
            return InputData(path,fmt,rows=rows,native=native)
        if fmt=='avro':
            rows=read_avro(path, raw_union=False); return InputData(path,fmt,rows=rows,native=rows)
        if fmt=='orc':
            rows=derive_orc_from_avro(path); return InputData(path,fmt,rows=rows,native=rows)
        if fmt=='parquet':
            rows=derive_parquet_from_sheet(path); return InputData(path,fmt,rows=rows,native=rows,bool_cols={'Activated'})
        if fmt=='txt':
            text=load_text(path, raw)
            try: native=json.loads(text)
            except Exception: native=text
            return InputData(path,fmt,rows=None,native=native,raw=text)
        raise DsqError(f'Unknown mimetype for file: {path}.')
    except FileNotFoundError:
        raise DsqError(f'open {path}: no such file or directory')
    except zipfile.BadZipFile:
        raise DsqError('zip: not a valid zip file')
    except json.JSONDecodeError as ex:
        raise DsqError(str(ex))

# ---------- SQL/output ----------

def ensure_rows(inp):
    if inp.rows is None:
        raise DsqError(f'Input is not an array of objects: {inp.name}.')
    return inp.rows

def create_table(conn, table, rows):
    cols=[]; seen=set()
    for r in rows:
        for k in r.keys():
            if k not in seen: seen.add(k); cols.append(k)
    if not cols:
        cols=['']
    conn.execute('CREATE TABLE %s (%s)'%(quote_ident(table), ','.join(quote_ident(c) for c in cols)))
    if rows:
        sql='INSERT INTO %s (%s) VALUES (%s)'%(quote_ident(table), ','.join(quote_ident(c) for c in cols), ','.join('?' for _ in cols))
        conn.executemany(sql, [[r.get(c) for c in cols] for r in rows])
    return cols

def rewrite_query(q):
    q=q.replace('{}','{0}')
    return re.sub(r'\{(\d+)\}', lambda m: 't'+m.group(1), q)

def split_select_list(s):
    parts=[]; cur=[]; depth=0; quote=None; i=0
    while i<len(s):
        ch=s[i]
        if quote:
            cur.append(ch)
            if ch==quote: quote=None
        else:
            if ch in ('"',"'"):
                quote=ch; cur.append(ch)
            elif ch=='(':
                depth+=1; cur.append(ch)
            elif ch==')':
                depth=max(0,depth-1); cur.append(ch)
            elif ch==',' and depth==0:
                parts.append(''.join(cur).strip()); cur=[]
            else: cur.append(ch)
        i+=1
    if cur: parts.append(''.join(cur).strip())
    return parts

def infer_result_bool_cols(query, input_bool_cols, desc_names):
    res=set()
    for n in desc_names:
        if n in input_bool_cols: res.add(n)
    m=re.search(r'(?is)^\s*select\s+(.*?)\s+from\s+', query)
    if not m: return res
    for expr in split_select_list(m.group(1)):
        # direct: [table.]col [as alias]
        alias=None; base=expr
        ma=re.match(r'(?is)(.*?)\s+as\s+("[^"]+"|\S+)\s*$', expr)
        if ma:
            base=ma.group(1).strip(); alias=ma.group(2).strip().strip('"')
        else:
            toks=expr.rsplit(None,1)
            if len(toks)==2 and not any(op in toks[1] for op in '+-*/()'):
                base,alias=toks[0],toks[1].strip('"')
        b=base.strip()
        if '.' in b and not b.startswith('"'):
            b=b.split('.')[-1]
        b=b.strip('"')
        if b in input_bool_cols:
            res.add(alias or b)
    return res

def value_for_display(v):
    if isinstance(v,(bytes,bytearray)):
        try: return v.decode('utf-8')
        except Exception: return v.hex()
    if v is None: return 'null'
    if isinstance(v,bool): return 'true' if v else 'false'
    return str(v)

def dump_pretty(rows):
    if not rows:
        print('[]')
        return
    cols=sorted({k for r in rows for k in r.keys()})
    vals={c:[value_for_display(r.get(c)) for r in rows] for c in cols}
    widths={c:max(len(c), *(len(x) for x in vals[c])) for c in cols}
    numeric={c: all((r.get(c) is None) or (isinstance(r.get(c),(int,float)) and not isinstance(r.get(c),bool)) or (isinstance(r.get(c),str) and re.fullmatch(r'-?\d+(\.\d+)?', r.get(c,''))) for r in rows) for c in cols}
    def border(): print('+' + '+'.join('-'*(widths[c]+2) for c in cols) + '+')
    border()
    print('|' + '|'.join(' '+c.center(widths[c])+' ' for c in cols) + '|')
    border()
    for i in range(len(rows)):
        cells=[]
        for c in cols:
            s=vals[c][i]
            cells.append(' '+(s.rjust(widths[c]) if numeric[c] else s.ljust(widths[c]))+' ')
        print('|'+'|'.join(cells)+'|')
    border()
    print(f'({len(rows)} rows)')

def run_query(inputs, query, pretty=False, interactive=False):
    conn=sqlite3.connect(':memory:')
    all_bool=set()
    for i,inp in enumerate(inputs):
        rows=ensure_rows(inp)
        create_table(conn, 't'+str(i), rows)
        all_bool |= set(inp.bool_cols)
    q=rewrite_query(query)
    cur=conn.execute(q)
    desc=[d[0] for d in cur.description] if cur.description else []
    bool_out=infer_result_bool_cols(query, all_bool, desc)
    out=[]
    for tup in cur.fetchall():
        row=OrderedDict()
        for k,v in zip(desc,tup):
            if isinstance(v, bytes):
                try: v=v.decode('utf-8')
                except Exception: v=v.hex()
            if k in bool_out and isinstance(v,int) and v in (0,1): v=bool(v)
            row[k]=v
        out.append(row)
    if pretty or interactive:
        dump_pretty(out)
    else:
        dump_json_rows(out)

def default_output(inp, pretty=False):
    if inp.fmt=='json' and inp.is_json_raw:
        # dsq preserves raw JSON and appends a newline in dump mode.
        sys.stdout.write(inp.raw)
        if not inp.raw.endswith('\n'): sys.stdout.write('\n')
        sys.stdout.write('\n')
        return
    rows=ensure_rows(inp)
    if pretty: dump_pretty(rows)
    else: dump_json_rows(rows, bool_cols=inp.bool_cols)

# ---------- CLI ----------

def parse_args(argv):
    opts={'pretty':False,'schema':False,'cache':False,'interactive':False,'stream_fmt':None,'query_file':None,'help':False,'version':False}
    pos=[]; i=0
    while i<len(argv):
        a=argv[i]
        if a in ('-h','--help'):
            opts['help']=True; i+=1
        elif a=='--version':
            opts['version']=True; i+=1
        elif a in ('-p','--pretty'):
            opts['pretty']=True; i+=1
        elif a=='--schema':
            opts['schema']=True; i+=1
        elif a in ('-C','--cache'):
            opts['cache']=True; i+=1
        elif a in ('-i','--interactive'):
            opts['interactive']=True; i+=1
        elif a=='-s':
            if i+1>=len(argv): raise DsqError('Missing value for -s')
            opts['stream_fmt']=argv[i+1]; i+=2
        elif a in ('-f','--file'):
            if i+1>=len(argv): raise DsqError('Missing sql file')
            opts['query_file']=argv[i+1]; i+=2
        else:
            pos.append(a); i+=1
    return opts,pos

def main(argv=None):
    argv=sys.argv[1:] if argv is None else argv
    try:
        opts,pos=parse_args(argv)
        if opts['version']:
            print('dsq latest'); return 0
        if opts['help']:
            print(HELP); return 0
        query=None
        if opts['query_file']:
            try:
                with open(opts['query_file'],'r',encoding='utf-8') as f: query=f.read()
            except FileNotFoundError:
                raise DsqError(f'Error opening sql file: open {opts["query_file"]}: no such file or directory')
        inputs=[]
        if opts['stream_fmt']:
            raw=sys.stdin.buffer.read()
            tmp='/tmp/dsq-stdin%d'%os.getpid()
            if pos and not opts['query_file']:
                query=pos[-1]
            inputs=[load_input(tmp, opts['stream_fmt'], raw=raw)]
        else:
            files=pos[:]
            if not opts['query_file'] and len(files)>1 and looks_like_query_arg(files[-1]):
                query=files[-1]; files=files[:-1]
            if not files:
                raise DsqError('No input files.')
            for f in files:
                fmt=detect_format(f)
                if not known_format(fmt):
                    raise DsqError(f'Unknown mimetype for file: {f}.')
                inputs.append(load_input(f, fmt))
        if opts['schema']:
            if not inputs: raise DsqError('No input files.')
            shape=infer_shape(inputs[0].native)
            print(json.dumps(shape, ensure_ascii=False, indent=2))
            return 0
        if opts['interactive']:
            # A small non-fancy REPL.  Each non-empty line is executed as SQL.
            code=0
            for line in sys.stdin:
                q=line.strip().rstrip(';')
                if not q: continue
                try: run_query(inputs, q, pretty=True, interactive=True)
                except Exception as ex:
                    print(str(ex)); code=1
            return code
        if query is None:
            if len(inputs)==1:
                default_output(inputs[0], pretty=opts['pretty'])
                return 0
            query='select * from {}'
        run_query(inputs, query, pretty=opts['pretty'])
        return 0
    except sqlite3.Error as ex:
        print(str(ex)); return 1
    except DsqError as ex:
        print(str(ex)); return 1
    except BrokenPipeError:
        return 0
    except Exception as ex:
        print(str(ex)); return 1

if __name__=='__main__':
    sys.exit(main())
